// Источник: web-тест .qa/e2e/tests/profile/pr-04-edit-preferences.spec.ts, план .qa/e2e/specs/profile.md, кейс .qa/tests/profile/PR-04-edit-preferences.md
// Тикет #6a86f7f9. Меняет נוסח user1 на ספרד и возвращает אשכנז. «reload» → перезаход в профиль.
// Часть «רמת התחזקות» (шаг слайдера стрелкой клавиатуры) на устройстве не воспроизводится надёжно — ручная проверка (COVERAGE).
import { $, expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, tapLabel, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

const labelOf = async (el: El) => (await el.getAttribute(driver.isAndroid ? 'content-desc' : 'label')) ?? '';
async function checked(el: El) {
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'true' || (await el.isSelected().catch(() => false));
}
function button(text: string) {
  return driver.isAndroid ? $(`//*[@text="${text}"]/ancestor-or-self::*[@clickable="true"][1]`) : byText(text);
}
async function openProfile() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await scrollToText('נוסח תפילה');
}
async function nusachLabel() {
  return labelOf(await byLabelStartsWith('נוסח תפילה: '));
}
async function saveNusach() {
  await (await button('שמירה')).click();
  await expectTextContains('נוסח: השינוי נשמר.');
  await expect(byTextContains('נוסח התפילה הספרדי והעדות המזרח')).not.toBeDisplayed();
}

describe('Профиль — вошедший пользователь', () => {
  afterEach(async () => { await toHome(); });

  it('PR-04 Правка נוסח — «השינוי נשמר», применяется на главной, переживает перезаход #6a86f7f9 @data', async () => {
    try {
      await openProfile();
      expect(await nusachLabel()).toBe('נוסח תפילה: אשכנז. מעבר לשלב כדי לשנות');

      // 2. «נוסח תפילה» → 2 варианта (нет «נוסח עדות המזרח · בקרוב», #32e3cd9a 21.10) → «נוסח ספרד / עדות המזרח» → «שמירה».
      await (await byLabelStartsWith('נוסח תפילה: ')).click();
      await expect(byLabelStartsWith('נוסח עדות המזרח')).not.toBeExisting();
      await expect(byLabelStartsWith('נוסח ספרד / עדות המזרח')).toBeExisting();
      expect(await checked(await byLabelStartsWith('נוסח אשכנז'))).toBe(true);
      await (await byLabelStartsWith('נוסח ספרד')).click();
      await driver.waitUntil(async () => checked(await byLabelStartsWith('נוסח ספרד')), { timeoutMsg: 'ספרד не выбран' });
      await saveNusach();

      // 3. Перезаход в профиль; главная показывает «נוסח ספרד».
      await openProfile();
      expect(await nusachLabel()).toBe('נוסח תפילה: ספרד. מעבר לשלב כדי לשנות');
      await toHome();
      await (await byText('נוסח ספרד')).waitForDisplayed({ timeout: 20000 });
    } finally {
      // 4. Уборка: вернуть «נוסח אשכנז».
      await openProfile();
      if ((await nusachLabel()).includes('ספרד')) {
        await (await byLabelStartsWith('נוסח תפילה: ')).click();
        await (await byLabelStartsWith('נוסח אשכנז')).click();
        await saveNusach();
      }
      await openProfile();
      expect(await nusachLabel()).toBe('נוסח תפילה: אשכנז. מעבר לשלב כדי לשנות');
      await toHome();
      await (await byText('נוסח אשכנז')).waitForDisplayed({ timeout: 20000 });
    }
  });
});
